<?php require_once __DIR__.'/../includes/bootstrap.php'; require_once __DIR__.'/../includes/link_service.php';$u=require_auth();if(!request_is_post())redirect('/dashboard.php');verify_csrf();$link=owns_link((int)($_POST['id']??0),(int)$u['id']);if(!$link){flash('error','Link not found.');redirect('/dashboard.php');}$action=$_POST['action']??'';if($action==='delete')db()->prepare('DELETE FROM short_links WHERE id=? AND user_id=?')->execute([$link['id'],$u['id']]);elseif(in_array($action,['enable','disable'],true))db()->prepare('UPDATE short_links SET is_active=? WHERE id=? AND user_id=?')->execute([$action==='enable',$link['id'],$u['id']]);else {flash('error','Invalid link action.');redirect('/dashboard.php');}flash('success','Link updated.');redirect('/dashboard.php');
